let selectedFiles=[];
function renderSelectedFiles(){const summary=document.getElementById('fileSummary');if(selectedFiles.length===0){summary.textContent='No files selected';return}const names=selectedFiles.slice(0,3).map(f=>f.name || 'file').join(', ');const more=selectedFiles.length>3?' +'+(selectedFiles.length-3)+' more':'';const bytes=selectedFiles.reduce((sum,file)=>sum+file.size,0);summary.textContent=names+more+' ('+fmtBytes(bytes)+')'}
function addFiles(files){selectedFiles=selectedFiles.concat(Array.from(files||[]));renderSelectedFiles()}
async function filePayload(file){return {name:file.name || 'upload',mimeType:file.type || 'application/octet-stream',dataBase64:await fileToBase64(file)}}
async function fileToBase64(file){const buffer=await file.arrayBuffer();const bytes=new Uint8Array(buffer);let binary='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk){binary+=String.fromCharCode(...bytes.subarray(i,i+chunk))}return btoa(binary)}
function createWebCorrelationId(){return (crypto.randomUUID?crypto.randomUUID().replace(/-/g,''):String(Date.now())+Math.random().toString(16).slice(2)).slice(0,12)}
document.getElementById('fileInput').onchange=e=>{if(!can('files.write')){toast('Permission required: files.write');return}addFiles(e.target.files)};
document.getElementById('clearFilesBtn').onclick=()=>{selectedFiles=[];document.getElementById('fileInput').value='';renderSelectedFiles()};
document.addEventListener('paste',e=>{const files=Array.from(e.clipboardData?.files||[]);if(files.length){if(!can('files.write')){toast('Permission required: files.write');return}addFiles(files);toast('Pasted '+files.length+' file(s)')}});
document.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('drop-active')});
document.addEventListener('dragleave',()=>document.body.classList.remove('drop-active'));
document.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('drop-active');const files=Array.from(e.dataTransfer?.files||[]);if(files.length){if(!can('files.write')){toast('Permission required: files.write');return}addFiles(files);toast('Added '+files.length+' dropped file(s)')}});
document.getElementById('promptInput').addEventListener('keydown',e=>{if(e.key!=='Enter'||e.isComposing)return;const input=e.currentTarget as HTMLTextAreaElement;if(e.ctrlKey){e.preventDefault();const start=input.selectionStart??input.value.length;const end=input.selectionEnd??start;input.setRangeText('\n',start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));return}e.preventDefault();(document.getElementById('promptForm') as HTMLFormElement|null)?.requestSubmit()});
document.getElementById('promptForm').onsubmit=e=>safe(async()=>{e.preventDefault();const input=document.getElementById('promptInput');const text=input.value.trim();if(/^\/mirror\b/i.test(text)){if(selectedFiles.length){toast('/mirror cannot be sent with attachments');return}const argument=text.replace(/^\/mirror\b/i,'').trim();if(argument&&!can('settings.write')){toast('Permission required: settings.write');return}if(!argument&&!can('sessions.read')){toast('Permission required: sessions.read');return}input.value='';const data=argument?await setMirrorPreference(argument):await loadMirrorPreference();appendMessage('system',data?.response?.plain||('CLI mirroring: '+(data?.mode||'-')));return}if(!can('prompt.send')){toast('Permission required: prompt.send');return}if(selectedFiles.length&&!can('files.write')){toast('Permission required: files.write');return}if(!text&&selectedFiles.length===0)return;const files=selectedFiles;const correlationId=createWebCorrelationId();input.value='';selectedFiles=[];document.getElementById('fileInput').value='';renderSelectedFiles();const payloadFiles=files.length?await Promise.all(files.map(filePayload)):[];const r=files.length?await api('/api/prompt/upload',{method:'POST',body:JSON.stringify({text,correlationId,files:payloadFiles})}):await api('/api/prompt',{method:'POST',body:JSON.stringify({text,correlationId})});if(r.transcribeOnly)appendMessage('system','Transcribed audio:\n'+(r.transcript||'(empty)'));else if(r.queued)appendQueuedMessage(r.queueId,r.correlationId||correlationId)},e);
document.getElementById('newSessionBtn').onclick=()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}openNewSessionDialog()};
document.getElementById('retryBtn').onclick=()=>safe(async()=>{if(!can('prompt.send')){toast('Permission required: prompt.send');return}const r=await api('/api/retry',{method:'POST'});toast(r.queued?'Retry queued '+r.queueId:'Retry started')});
document.getElementById('syncBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const r=await api('/api/sync',{method:'POST'});toast(r.changed?'Synced: '+(r.changedFields||[]).join(', '):'Already in sync');loadBootstrap()});
document.getElementById('notifyBtn').onclick=()=>enableNotifications();
document.getElementById('mirrorModeSelect').onchange=()=>safe(async()=>{if(!can('settings.write')){toast('Permission required: settings.write');renderMirrorPreference(state.webMirror);return}await setMirrorPreference(document.getElementById('mirrorModeSelect').value)});
document.getElementById('clearChatBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}if(confirm('Clear chat history for the current thread?')){const r=await api('/api/chat/history',{method:'DELETE'});renderChatMessages(r.messages||[]);toast('Removed '+r.removed+' messages')}});
document.getElementById('abortBtn').onclick=()=>safe(async()=>{if(!can('prompt.abort')){toast('Permission required: prompt.abort');return}await api('/api/abort',{method:'POST'});toast('Abort sent')});
document.getElementById('recordBtn').onclick=()=>safe(async()=>{if(!can('files.write')){toast('Permission required: files.write');return}const btn=document.getElementById('recordBtn');if(state.mediaRecorder&&state.mediaRecorder.state==='recording'){state.mediaRecorder.stop();btn.textContent='Record voice';return}const stream=await navigator.mediaDevices.getUserMedia({audio:true});state.recordedChunks=[];state.mediaRecorder=new MediaRecorder(stream);state.mediaRecorder.ondataavailable=e=>{if(e.data.size>0)state.recordedChunks.push(e.data)};state.mediaRecorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(state.recordedChunks,{type:'audio/webm'});addFiles([new File([blob],'voice-note.webm',{type:'audio/webm'})]);toast('Voice note attached')};state.mediaRecorder.start();btn.textContent='Stop recording'});
function renderMirrorPreference(data){if(!data)return;state.webMirror=data;const select=document.getElementById('mirrorModeSelect');if(select&&data.mode)select.value=data.mode}
async function loadMirrorPreference(){if(!can('sessions.read'))return null;const data=await api('/api/chat/mirror');renderMirrorPreference(data);return data}
async function setMirrorPreference(argument){const data=await api('/api/chat/mirror',{method:'POST',body:JSON.stringify({argument})});renderMirrorPreference(data);toast('Mirror '+data.mode);return data}
function renderNewSessionControls(c){const s=state.snapshot?.session||{};const caps=c.capabilities||{};document.getElementById('workspaceOptions').innerHTML=(c.workspaces||[]).map(w=>'<option value="'+attr(w)+'"></option>').join('');document.getElementById('newModel').innerHTML='<option value="">Default</option>'+((c.models||[]).map(m=>'<option value="'+attr(m.slug)+'">'+esc(modelLabel(m))+'</option>').join(''));document.getElementById('newModel').parentElement.style.display=caps.modelSelection?'grid':'none';const reasoningWrap=document.getElementById('newReasoningWrap');reasoningWrap.firstChild.nodeValue=(c.reasoningLabel||'Reasoning');reasoningWrap.style.display=caps.reasoningSelection?'grid':'none';document.getElementById('newReasoning').innerHTML='<option value="">Default</option>'+((c.reasoningOptions||[]).map(v=>'<option value="'+attr(v)+'">'+esc(v)+'</option>').join(''));document.getElementById('newLaunch').innerHTML='<option value="">Default</option>'+((c.launchProfiles||[]).map(p=>'<option value="'+attr(p.id)+'">'+esc(p.label+' - '+p.behavior)+'</option>').join(''));document.getElementById('newFast').checked=Boolean(s.fastMode&&caps.fastMode);document.getElementById('newLaunchWrap').style.display=caps.launchProfiles?'grid':'none';document.getElementById('newFastWrap').style.display=caps.fastMode?'inline-flex':'none'}
function populateNewSessionForm(agents){const s=state.snapshot?.session||{};const agentSelect=document.getElementById('newAgent');agentSelect.innerHTML=(agents||[]).map(a=>'<option value="'+attr(a)+'" '+(a===s.agentId?'selected':'')+'>'+esc(a)+'</option>').join('');agentSelect.value=s.agentId||agentSelect.value;document.getElementById('newWorkspace').value=s.workspace||'';const mode=document.getElementById('newWorkspaceMode');if(mode)mode.value='';state.newSessionControls=state.controls||{};renderNewSessionControls(state.newSessionControls);agentSelect.onchange=()=>safe(async()=>{state.newSessionControls=await api('/api/control-options',{query:{agent:agentSelect.value}});renderNewSessionControls(state.newSessionControls)})}
function openNewSessionDialog(){populateNewSessionForm(state.enabledAgents);document.getElementById('newSessionDialog').showModal()}
document.getElementById('newSessionForm').onsubmit=e=>safe(async()=>{e.preventDefault();if(!can('sessions.write')){toast('Permission required: sessions.write');return}const payload={agentId:val('newAgent'),workspace:val('newWorkspace')||undefined,workspaceMode:val('newWorkspaceMode')||undefined,model:val('newModel')||undefined,reasoningEffort:val('newReasoning')||undefined,launchProfileId:val('newLaunch')||undefined,fastMode:document.getElementById('newFast').checked};await api('/api/sessions/new',{method:'POST',body:JSON.stringify(payload)});document.getElementById('newSessionDialog').close();toast(payload.workspaceMode==='worktree'?'Isolated worktree session started':'New session started');await loadBootstrap();await loadChatHistory({forceScroll:true});if(state.currentPage==='sessions')loadSessions(true)},e);
document.getElementById('cancelSessionBtn').onclick=()=>document.getElementById('newSessionDialog').close();
function val(id){return document.getElementById(id).value.trim()}
function activeAgentId(){return state.snapshot?.session?.agentId||''}
function shortMiddle(value,edge=6,max=15){const text=String(value??'');if(text.length<=max)return text;return text.slice(0,edge)+'...'+text.slice(-edge)}
function sessionRelativeTimeHtml(timestamp){return '<span class="session-age" data-session-age-at="'+attr(timestamp||'')+'" title="'+attr(fmtDate(timestamp))+'">'+esc(fmtSessionAge(timestamp))+'</span>'}
function sessionAgeHtml(s){return sessionRelativeTimeHtml(s.createdAt||s.updatedAt)}
function sessionCell(label,html,cls=''){return '<td data-label="'+attr(label)+'"'+(cls?' class="'+cls+'"':'')+'>'+html+'</td>'}
function sessionModeBadge(s){const mode=s.workspaceMode||'attached';const label=mode==='worktree'?'Worktree':mode==='shared'?'Shared':'Attached';const title=s.worktree?('Branch: '+s.worktree.branchName+' / Base: '+s.worktree.baseSha):mode;return '<span class="adapter-status '+(mode==='worktree'?'enabled':mode==='shared'?'planned':'disabled')+'" title="'+attr(title)+'">'+esc(label)+'</span>'}
function renderSessionRow(s){const title=s.title||s.firstUserMessage||s.id;const thread='<button type="button" class="copy-id" data-copy-id="'+attr(s.id)+'" title="'+attr(s.id)+'">'+esc(shortMiddle(s.id))+'</button>';const actions='<div class="data-table-actions"><button data-switch="'+attr(s.id)+'"'+disabledAttr('sessions.write')+'>Switch</button><button class="secondary" data-session-detail="'+attr(s.id)+'">Details</button></div>';return '<tr>'+sessionCell('Updated',sessionRelativeTimeHtml(s.updatedAt),'updated-cell')+sessionCell('Title','<span class="truncate-cell" title="'+attr(title)+'">'+esc(short(title,120))+'</span>','primary-cell')+sessionCell('Thread ID',thread,'thread-cell')+sessionCell('Workspace','<span class="truncate-cell" title="'+attr(s.cwd||'')+'">'+esc(short(s.cwd||'-',120))+'</span>','workspace-cell')+sessionCell('Mode',sessionModeBadge(s),'optional-model')+sessionCell('Agent',esc(s.agentLabel||s.agentId||'-'),'optional-agent')+sessionCell('Model','<span class="truncate-cell" title="'+attr(s.model||'')+'">'+esc(short(s.model||'-',64))+'</span>','optional-model')+sessionCell('Age',sessionAgeHtml(s),'age-cell')+sessionCell('Actions',actions,'actions-cell')+'</tr>'}
function renderSessionsTable(sessions){if(!sessions.length)return '<div class="item">No sessions found.</div>';return '<div class="data-table-wrap"><table class="data-table sessions-table"><thead><tr><th>Updated</th><th>Title</th><th>Thread ID</th><th>Workspace</th><th>Mode</th><th class="optional-agent">Agent</th><th class="optional-model">Model</th><th>Age</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+sessions.map(renderSessionRow).join('')+'</tbody></table></div>'}
async function loadSessions(reset=true,agentId=''){if(reset)sessionsPager.reset();const expectedAgent=agentId||activeAgentId();const requestId=++state.sessionsRequestId;setLoading('sessionsList','Loading '+(expectedAgent||'agent')+' sessions...');const q=document.getElementById('sessionSearch').value||'';const data=await api('/api/sessions',{query:{query:q,page:sessionsPager.page,limit:sessionsPager.pageSize,agent:expectedAgent||undefined}});if(requestId!==state.sessionsRequestId||expectedAgent!==activeAgentId())return;document.getElementById('sessionsList').innerHTML=renderSessionsTable(data.sessions||[]);sessionsPager.render(data.pagination||{});startSessionAgeCounter();document.querySelectorAll('[data-copy-id]').forEach(b=>b.onclick=()=>copyText(b.dataset.copyId||'','Thread ID copied'));document.querySelectorAll('[data-switch]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}await api('/api/sessions/switch',{method:'POST',body:{threadId:b.dataset.switch}});toast('Session switched');loadBootstrap()}));document.querySelectorAll('[data-session-detail]').forEach(b=>b.onclick=()=>safe(()=>loadSessionDetail(b.dataset.sessionDetail)));applyPermissions()}
function switchSessionTab(tab){state.sessionTab=tab||'sessions';document.querySelectorAll('[data-session-tab]').forEach(b=>{const active=b.dataset.sessionTab===state.sessionTab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');b.tabIndex=active?0:-1});document.querySelectorAll('[data-session-tab-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.sessionTabPanel===state.sessionTab));if(state.sessionTab==='worktrees')safe(loadWorktrees)}
function renderWorktreeWarnings(warnings){const target=document.getElementById('worktreeWarnings');if(!target)return;target.innerHTML=(warnings||[]).map(w=>'<div class="item warning"><strong>Shared workspace collision</strong><small>'+esc(w.repoRoot)+' has '+w.sessions.length+' active/known sessions without isolated worktrees.</small></div>').join('')}
function renderWorktreeRows(records){if(!records.length)return '<div class="item">No session worktrees yet.</div>';const rows=records.map(r=>{const checkbox='<input type="checkbox" data-worktree-select="'+attr(r.id)+'" '+(r.commitSha?'':'disabled')+'>';const thread=r.threadId?'<button type="button" class="copy-id" data-copy-id="'+attr(r.threadId)+'" title="'+attr(r.threadId)+'">'+esc(shortMiddle(r.threadId))+'</button>':'-';const status='<span class="adapter-status '+(r.statusText==='dirty'?'planned':r.statusText==='merged'?'enabled':r.statusText.includes('conflict')?'disabled':'')+'">'+esc(r.statusText)+'</span>';const actions='<div class="data-table-actions"><button data-worktree-diff="'+attr(r.id)+'">Diff</button><button class="secondary" data-worktree-update="'+attr(r.id)+'"'+disabledAttr('sessions.write')+'>Update</button><button data-worktree-commit="'+attr(r.id)+'"'+disabledAttr('sessions.write')+'>Commit</button><button class="secondary" data-worktree-remove="'+attr(r.id)+'"'+disabledAttr('sessions.write')+'>Remove</button></div>';return '<tr><td data-label="Select">'+checkbox+'</td><td data-label="Status">'+status+'</td><td data-label="Thread ID">'+thread+'</td><td data-label="Branch"><span class="truncate-cell" title="'+attr(r.branchName)+'">'+esc(short(r.branchName,80))+'</span></td><td data-label="Path"><span class="truncate-cell" title="'+attr(r.worktreePath)+'">'+esc(short(r.worktreePath,120))+'</span></td><td data-label="Base"><code title="'+attr(r.baseSha)+'">'+esc(shortMiddle(r.baseSha,7,17))+'</code></td><td data-label="Commit"><code title="'+attr(r.commitSha||'')+'">'+esc(r.commitSha?shortMiddle(r.commitSha,7,17):'-')+'</code></td><td data-label="Actions" class="actions-cell">'+actions+'</td></tr>'}).join('');return '<div class="data-table-wrap"><table class="data-table sessions-table worktrees-table"><thead><tr><th></th><th>Status</th><th>Thread ID</th><th>Branch</th><th>Path</th><th>Base</th><th>Commit</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}
function integrationStatusClass(status){if(status==='merged'||status==='applied')return'enabled';if(status==='conflict'||status==='failed')return'disabled';return'planned'}
function renderWorktreeIntegrations(runs){const target=document.getElementById('worktreeIntegrations');if(!target)return;const list=(runs||[]).slice(0,12);if(!list.length){target.innerHTML=uiEmpty('No integration runs yet.');return}target.innerHTML='<div class="data-table-wrap"><table class="data-table worktree-integrations-table"><thead><tr><th>Updated</th><th>Branch</th><th>Status</th><th>Target</th><th>Path</th><th>Commits</th><th>Resolved</th><th>Error</th><th class="actions-heading">Actions</th></tr></thead><tbody>'+list.map(run=>{const commits=run.mergedCommitShas||run.sourceCommits||[];const resolved=run.resolvedConflicts||[];const targetBranch=run.targetBranch||run.baseBranch||'-';const actions=run.status==='merged'?'<div class="data-table-actions"><button data-worktree-integration-finalize="'+attr(run.id)+'"'+disabledAttr('sessions.write')+'>Finalize</button></div>':run.status==='applied'?'<small title="'+attr(run.appliedCommitSha||'')+'">Applied</small>':'-';return '<tr>'+sessionCell('Updated',sessionRelativeTimeHtml(run.updatedAt),'updated-cell')+sessionCell('Branch','<span class="truncate-cell" title="'+attr(run.branchName||'-')+'">'+esc(short(run.branchName||'-',120))+'</span>','primary-cell')+sessionCell('Status','<span class="adapter-status '+integrationStatusClass(run.status)+'">'+esc(run.status)+'</span>','status-cell')+sessionCell('Target','<span class="truncate-cell" title="'+attr(targetBranch)+'">'+esc(short(targetBranch,80))+'</span>')+sessionCell('Path','<span class="truncate-cell" title="'+attr(run.worktreePath||'-')+'">'+esc(short(run.worktreePath||'-',140))+'</span>')+sessionCell('Commits','<span class="truncate-cell" title="'+attr(commits.join(', ')||'-')+'">'+esc(commits.length||'-')+'</span>')+sessionCell('Resolved','<span class="truncate-cell" title="'+attr(resolved.join(', ')||'-')+'">'+esc(resolved.length||'-')+'</span>')+sessionCell('Error','<span class="truncate-cell '+(run.lastError?'error':'')+'" title="'+attr(run.lastError||'-')+'">'+esc(short(run.lastError||'-',180))+'</span>')+sessionCell('Actions',actions,'actions-cell')+'</tr>'}).join('')+'</tbody></table></div>';startSessionAgeCounter()}
async function loadWorktrees(){if(!can('sessions.read'))return;setLoading('worktreesList','Loading worktrees...');const data=await api('/api/sessions/worktrees');state.worktrees=data;renderWorktreeWarnings(data.sharedWarnings||[]);document.getElementById('worktreesList').innerHTML=renderWorktreeRows(data.records||[]);renderWorktreeIntegrations(data.integrations||[]);document.querySelectorAll('[data-copy-id]').forEach(b=>b.onclick=()=>copyText(b.dataset.copyId||'','Thread ID copied'));document.querySelectorAll('[data-worktree-diff]').forEach(b=>b.onclick=()=>safe(()=>showWorktreeDiff(b.dataset.worktreeDiff)));document.querySelectorAll('[data-worktree-update]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const result=await api('/api/sessions/worktrees/'+encodeURIComponent(b.dataset.worktreeUpdate)+'/update',{method:'POST',body:JSON.stringify({})});toast(result.record?.status==='conflict'?'Worktree update has conflicts':result.rebased?'Worktree updated from base':'Worktree already current');loadWorktrees()}));document.querySelectorAll('[data-worktree-commit]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const message=prompt('Commit message','NordRelay session '+b.dataset.worktreeCommit)||undefined;const result=await api('/api/sessions/worktrees/'+encodeURIComponent(b.dataset.worktreeCommit)+'/commit',{method:'POST',body:JSON.stringify({message})});toast(result.clean?'Worktree clean':'Worktree committed');loadWorktrees()}));document.querySelectorAll('[data-worktree-remove]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}if(confirm('Remove this worktree?')){await api('/api/sessions/worktrees/'+encodeURIComponent(b.dataset.worktreeRemove),{method:'DELETE',body:JSON.stringify({force:true})});toast('Worktree removed');loadWorktrees()}}));document.querySelectorAll('[data-worktree-integration-finalize]').forEach(b=>b.onclick=()=>safe(()=>openFinalizeIntegrationDialog(b.dataset.worktreeIntegrationFinalize)));applyPermissions()}

function openFinalizeIntegrationDialog(id){if(!can('sessions.write')){toast('Permission required: sessions.write');return}const run=(state.worktrees?.integrations||[]).find(item=>item.id===id);if(!run){toast('Integration run not found');return}const target=run.targetBranch||run.baseBranch||'';adminDialog('Finalize integration','<div class="full-span"><p>Apply the integration branch back into the original repository. The repository must be on the target branch and have a clean working tree.</p><div class="form-grid"><label>Target branch<input id="finalizeTargetBranch" value="'+attr(target)+'" placeholder="current branch"></label><label class="checkbox"><input id="finalizeRemoveIntegration" type="checkbox" checked> Remove integration worktree</label><label class="checkbox"><input id="finalizeRemoveSources" type="checkbox"> Remove source worktrees</label><label class="checkbox"><input id="finalizeDeleteBranch" type="checkbox"> Delete integration branch after apply</label></div><small>Branch: '+esc(run.branchName||'-')+'</small></div>',async()=>{const result=await api('/api/sessions/worktrees/integrations/'+encodeURIComponent(id)+'/finalize',{method:'POST',body:JSON.stringify({targetBranch:val('finalizeTargetBranch')||undefined,removeIntegrationWorktree:document.getElementById('finalizeRemoveIntegration').checked,removeSourceWorktrees:document.getElementById('finalizeRemoveSources').checked,deleteIntegrationBranch:document.getElementById('finalizeDeleteBranch').checked})});const warnings=result.run?.cleanup?.warnings||[];toast('Integration applied'+(warnings.length?' with '+warnings.length+' cleanup warning(s)':''),{duration:warnings.length?9000:4000});await loadWorktrees()},{submitText:'Finalize',reloadAccess:false})}

async function showWorktreeDiff(id){const result=await api('/api/sessions/worktrees/'+encodeURIComponent(id)+'/diff');const fileList=(result.files||[]).map(f=>f.status+' '+f.path).join('\n')||'No changed files.';adminDialog('Worktree diff','<div class="full-span"><small>'+esc(fileList)+'</small><pre class="artifact-diff-pre">'+esc(result.diff||'No diff.')+'</pre>'+(result.truncated?'<small>Diff truncated.</small>':'')+'</div>',async()=>{}, {submitText:'Close',reloadAccess:false})}
function worktreeSourceName(source,preview){const id=typeof source==='string'?source:source?.id;const found=(preview.sourceWorktrees||[]).find(s=>s.id===id);return found?.branchName||found?.threadId||id||'-'}
function worktreeConflictSourceOptions(item,preview){const sources=item.sourceWorktrees||[];return '<select data-worktree-resolution-source="'+attr(item.path)+'">'+sources.map(source=>{const id=typeof source==='string'?source:source.id;return '<option value="'+attr(id)+'">'+esc(worktreeSourceName(id,preview))+'</option>'}).join('')+'</select>'}
function worktreeResolutionControls(item,preview){if(item.risk==='none')return '-';return '<div class="worktree-resolution-controls"><select data-worktree-resolution-path="'+attr(item.path)+'"><option value="auto">Stop for manual Git conflict</option><option value="ours">Keep integration/base side</option><option value="theirs">Use selected source</option><option value="both">Combine all source versions</option><option value="manual">Use manual content</option></select>'+worktreeConflictSourceOptions(item,preview)+'<textarea data-worktree-resolution-content="'+attr(item.path)+'" rows="3" placeholder="Manual file content"></textarea></div>'}
function worktreeVersionPreviewBlock(version){if(!version)return'';const title=(version.label||version.branchName||version.worktreeId||'version')+(version.truncated?' · truncated':'');const body=version.content!==undefined?'<pre class="artifact-diff-pre">'+esc(version.content||'')+'</pre>':'<small>'+esc(version.unavailable||'Unavailable')+'</small>';return '<details class="worktree-version-preview"><summary>'+esc(title)+'</summary>'+body+'</details>'}
function worktreeVersionPreviews(item){const blocks=[worktreeVersionPreviewBlock(item.baseContent)].concat((item.sourceVersions||[]).map(worktreeVersionPreviewBlock)).join('');return blocks?'<details class="worktree-conflict-versions"><summary>File versions</summary>'+blocks+'</details>':''}
function worktreeConflictReviewTable(preview){const items=preview.conflictReview||[];if(!items.length)return uiEmpty('No changed files in selected worktrees.');return '<div class="data-table-wrap"><table class="data-table worktree-conflict-table"><thead><tr><th>Risk</th><th>File</th><th>Status</th><th>Sources</th><th>Resolution</th><th>Recommendation</th></tr></thead><tbody>'+items.map(item=>{const sourceNames=(item.sourceWorktrees||[]).map(source=>worktreeSourceName(source,preview)).join(', ');return '<tr>'+sessionCell('Risk','<span class="adapter-status '+(item.risk==='none'?'enabled':item.risk==='same-file'?'planned':'disabled')+'">'+esc(item.risk)+'</span>','status-cell')+sessionCell('File','<span class="truncate-cell" title="'+attr(item.path)+'">'+esc(short(item.path,180))+'</span>'+worktreeVersionPreviews(item),'primary-cell')+sessionCell('Status',esc(item.status||'-'))+sessionCell('Sources','<span class="truncate-cell" title="'+attr(sourceNames)+'">'+esc(short(sourceNames||'-',160))+'</span>')+sessionCell('Resolution',worktreeResolutionControls(item,preview),'actions-cell')+sessionCell('Recommendation','<span class="truncate-cell" title="'+attr(item.recommendation||'-')+'">'+esc(short(item.recommendation||'-',220))+'</span>')+'</tr>'}).join('')+'</tbody></table></div>'}
function worktreePreviewSourcesTable(preview){const sources=preview.sourceWorktrees||[];if(!sources.length)return'';return '<h3 class="table-section-title">Sources</h3><div class="data-table-wrap"><table class="data-table worktree-preview-sources-table"><thead><tr><th>Branch</th><th>Thread</th><th>Status</th><th>Path</th><th>Commit</th></tr></thead><tbody>'+sources.map(s=>'<tr>'+sessionCell('Branch','<span class="truncate-cell" title="'+attr(s.branchName||'-')+'">'+esc(short(s.branchName||'-',120))+'</span>','primary-cell')+sessionCell('Thread',s.threadId?'<button type="button" class="copy-id" data-copy-id="'+attr(s.threadId)+'" title="'+attr(s.threadId)+'">'+esc(shortMiddle(s.threadId))+'</button>':'-')+sessionCell('Status','<span class="adapter-status '+(s.statusText==='clean'?'enabled':s.statusText?.includes('conflict')?'disabled':'planned')+'">'+esc(s.statusText||'-')+'</span>','status-cell')+sessionCell('Path','<span class="truncate-cell" title="'+attr(s.worktreePath||'-')+'">'+esc(short(s.worktreePath||'-',140))+'</span>')+sessionCell('Commit','<code title="'+attr(s.commitSha||'')+'">'+esc(s.commitSha?shortMiddle(s.commitSha,7,17):'-')+'</code>')+'</tr>').join('')+'</tbody></table></div>'}
function worktreeIntegrationPreviewHtml(preview){const warnings=(preview.warnings||[]).length?'<div class="peer-warning full-span"><strong>Warnings</strong>'+(preview.warnings||[]).map(w=>'<small>'+esc(w)+'</small>').join('')+'</div>':'<div class="item"><strong>Ready to integrate</strong><small>No warnings reported by the preview.</small></div>';return '<div class="full-span">'+warnings+worktreePreviewSourcesTable(preview)+'<h3 class="table-section-title">Conflict review</h3>'+worktreeConflictReviewTable(preview)+'</div>'}

function selectedWorktreeIds(){return [...document.querySelectorAll('[data-worktree-select]:checked')].map(el=>el.dataset.worktreeSelect).filter(Boolean)}
function collectWorktreeResolutions(root){const scope=root||document;return [...scope.querySelectorAll('[data-worktree-resolution-path]')].map(select=>{const path=select.dataset.worktreeResolutionPath;const choice=select.value;return {path,choice,sourceWorktreeId:scope.querySelector('[data-worktree-resolution-source="'+cssEscape(path)+'"]')?.value||undefined,content:scope.querySelector('[data-worktree-resolution-content="'+cssEscape(path)+'"]')?.value||undefined}}).filter(item=>item.path&&item.choice&&item.choice!=='auto')}
document.querySelectorAll('[data-session-tab]').forEach(b=>b.onclick=()=>switchSessionTab(b.dataset.sessionTab));
document.getElementById('reloadWorktreesBtn').onclick=()=>safe(loadWorktrees);
document.getElementById('forkWorktreeBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const include=document.getElementById('forkIncludeUncommitted').checked;if(include&&!confirm('Copy tracked diff and untracked files from the current workspace into a new worktree?'))return;const result=await api('/api/sessions/worktrees/fork',{method:'POST',body:JSON.stringify({includeUncommitted:include})});toast('Forked into '+result.record.branchName);await loadBootstrap();await loadWorktrees();if(state.currentPage==='chat')await loadChatHistory({forceScroll:true})});
document.getElementById('integrateWorktreesBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const ids=selectedWorktreeIds();if(!ids.length){toast('Select committed worktrees first');return}const preview=await api('/api/sessions/worktrees/integrate/preview',{method:'POST',body:JSON.stringify({ids})});const risky=(preview.conflictReview||[]).filter(item=>item.risk!=='none');const resolutions=state.worktreeConflictResolutions||[];if((preview.warnings?.length||risky.length)&&!resolutions.length&&!confirm('Integration has '+(preview.warnings?.length||0)+' warning(s) and '+risky.length+' file risk(s). Open Preview to inspect and save resolutions.\n\nContinue without saved resolutions?'))return;const result=await api('/api/sessions/worktrees/integrate',{method:'POST',body:JSON.stringify({ids,resolutions})});toast(result.run.status==='merged'?'Integration branch created'+(result.run.resolvedConflicts?.length?' with '+result.run.resolvedConflicts.length+' resolved conflict(s)':''):'Integration '+result.run.status,{duration:8000});state.worktreeConflictResolutions=[];loadWorktrees()});
document.getElementById('previewWorktreeIntegrationBtn').onclick=()=>safe(async()=>{const ids=selectedWorktreeIds();if(!ids.length){toast('Select committed worktrees first');return}const p=await api('/api/sessions/worktrees/integrate/preview',{method:'POST',body:JSON.stringify({ids})});const risky=(p.conflictReview||[]).some(item=>item.risk!=='none');adminDialog('Integration preview',worktreeIntegrationPreviewHtml(p),async()=>{state.worktreeConflictResolutions=collectWorktreeResolutions(document.getElementById('adminDialog'));toast(state.worktreeConflictResolutions.length+' conflict resolution(s) saved')}, {submitText:risky?'Save resolutions':'Close',reloadAccess:false});bindUiCopyButtons(document.getElementById('adminDialog'))});
const exportWorktreePatchBtn=document.getElementById('exportWorktreePatchBtn');
if(exportWorktreePatchBtn)exportWorktreePatchBtn.onclick=()=>safe(async()=>{const ids=selectedWorktreeIds();if(!ids.length){toast('Select committed worktrees first');return}const patch=await api('/api/sessions/worktrees/integrate/patch',{method:'POST',body:JSON.stringify({ids})});downloadTextFile(patch.fileName||'nordrelay-worktree-patches.patch',patch.content||'','text/x-patch');toast('Patch exported')});
document.getElementById('cleanupWorktreesBtn').onclick=()=>safe(async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const result=await api('/api/sessions/worktrees/cleanup',{method:'POST',body:JSON.stringify({})});toast('Cleanup removed '+(result.removedRecords||[]).length+' stale record(s)');loadWorktrees()});
function usageRows(rows){return (rows||[]).map(row=>{if(Array.isArray(row))return [row[0],row[1]];const text=String(row);const index=text.indexOf(':');return index>0?[text.slice(0,index),text.slice(index+1).trim()]:[text,'']})}
function detailSection(title,count,body=''){return '<details class="session-detail-section"><summary>'+esc(title+' ('+count+')')+'</summary><div class="list">'+(body||'<div class="item">No entries.</div>')+'</div></details>'}
async function loadSessionDetail(threadId){const d=await api('/api/sessions/detail',{query:{threadId}});const r=d.record||{};const messages=d.messages||[];const activity=d.activity||[];const metadataRows=[['Thread',threadId],['Agent',r.agentId],['Title',r.title],['Workspace',r.cwd],['Model',r.model],['Reasoning',r.reasoningEffort],['Updated',fmtDate(r.updatedAt)],['Path',r.sessionPath]].concat(usageRows(d.usageRows));const messageItems=messages.slice(-20).map(m=>'<div class="item"><strong>'+esc(m.role+' / '+fmtDate(m.timestamp))+'</strong><small>'+esc(short(m.text,500))+'</small></div>').join('');const activityItems=activity.map(e=>'<div class="item"><strong>'+esc(e.status+' / '+e.type+' / '+fmtDate(e.timestamp))+'</strong><small>'+esc(short(e.prompt||e.detail||'',300))+'</small></div>').join('');document.getElementById('sessionDetail').innerHTML='<h2>Session detail</h2>'+card('Metadata',metadataRows)+detailSection('Recent messages',messages.length,messageItems)+detailSection('Activity',activity.length,activityItems);document.getElementById('sessionDetailDialog').showModal()}
document.getElementById('closeSessionDetailBtn').onclick=()=>document.getElementById('sessionDetailDialog').close();
document.getElementById('sessionSearchBtn').onclick=()=>loadSessions(true);document.getElementById('sessionSearch').addEventListener('keydown',e=>{if(e.key==='Enter')loadSessions(true)});document.getElementById('attachBtn').onclick=async()=>{if(!can('sessions.write')){toast('Permission required: sessions.write');return}const threadId=document.getElementById('attachInput').value.trim();if(threadId){await api('/api/sessions/attach',{method:'POST',body:JSON.stringify({threadId})});toast('Session attached');loadBootstrap()}};
function renderQueue(queue=[],paused=false){document.getElementById('queueStatus').textContent=paused?'Paused':'Running';document.getElementById('queueList').innerHTML=(queue||[]).map((q,i)=>'<div class="item queue-item" draggable="true" data-queue-id="'+attr(q.id)+'"><strong>'+esc((i+1)+'. '+q.id+' - '+q.description)+'</strong><small>Created '+fmtDate(q.createdAt)+' / attempts '+q.attempts+(q.correlationId?' / '+uiTraceControls(q.correlationId):'')+(q.lastError?' / '+esc(q.lastError):'')+'</small><div class="row"><button data-q="run" data-id="'+q.id+'"'+disabledAttr('queue.write')+'>Run</button><button data-q="top" data-id="'+q.id+'"'+disabledAttr('queue.write')+'>Top</button><button data-q="up" data-id="'+q.id+'"'+disabledAttr('queue.write')+'>Up</button><button data-q="down" data-id="'+q.id+'"'+disabledAttr('queue.write')+'>Down</button><button data-q="cancel" data-id="'+q.id+'" class="danger"'+disabledAttr('queue.write')+'>Cancel</button></div></div>').join('')||uiEmpty('Queue is empty.');bindUiCopyButtons(document.getElementById('queueList'));bindUiTraceButtons(document.getElementById('queueList'));document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('queue.write')){toast('Permission required: queue.write');return}const r=await api('/api/queue',{method:'POST',body:JSON.stringify({action:b.dataset.q,id:b.dataset.id})});renderQueue(r.queue,r.paused)}));let dragged=null;document.querySelectorAll('.queue-item').forEach(item=>{item.ondragstart=()=>{if(!can('queue.write'))return;dragged=item.dataset.queueId;item.classList.add('dragging')};item.ondragend=()=>item.classList.remove('dragging');item.ondragover=e=>{if(can('queue.write'))e.preventDefault()};item.ondrop=()=>safe(async()=>{if(!can('queue.write')){toast('Permission required: queue.write');return}if(dragged&&dragged!==item.dataset.queueId){const ids=Array.from(document.querySelectorAll('.queue-item')).map(el=>el.dataset.queueId);const targetIndex=Math.max(0,ids.indexOf(item.dataset.queueId));await api('/api/queue',{method:'POST',body:JSON.stringify({action:'top',id:dragged})});for(let i=0;i<targetIndex;i++)await api('/api/queue',{method:'POST',body:JSON.stringify({action:'down',id:dragged})});const r=await api('/api/queue');renderQueue(r.queue,r.paused)}})});applyPermissions()}
document.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('queue.write')){toast('Permission required: queue.write');return}const r=await api('/api/queue',{method:'POST',body:JSON.stringify({action:b.dataset.queue})});renderQueue(r.queue,r.paused)}));
async function loadArtifacts(reset=true){if(reset)artifactPager.reset();setLoading('artifactList','Loading artifacts...');document.getElementById('artifactPreview').innerHTML='';const [data,usage]=await Promise.all([api('/api/artifacts',{query:{limit:50,cursor:artifactPager.cursor||undefined,search:val('artifactSearch')||undefined,kind:val('artifactKind')||'all'}}),api('/api/artifacts/usage').catch(error=>({error:error.message||String(error)}))]);state.artifactReports=data.reports||[];state.artifactUsage=usage;renderArtifactUsage(usage);renderArtifacts();artifactPager.render(data.pagination||{})}
function artifactMatches(a,kind,query){const name=(a.name||a.relativePath||'').toLowerCase();if(query&&!name.includes(query))return false;if(kind==='images')return /\\.(png|jpe?g|gif|webp|svg)$/i.test(name);if(kind==='docs')return !/\\.(png|jpe?g|gif|webp|svg)$/i.test(name);return true}
document.getElementById('reloadArtifactsBtn').onclick=()=>loadArtifacts(true);
function queueArtifactReload(){clearTimeout(state.artifactSearchTimer);state.artifactSearchTimer=setTimeout(()=>loadArtifacts(true),250)}
document.getElementById('artifactSearch').oninput=()=>safe(queueArtifactReload);
document.getElementById('artifactKind').onchange=()=>safe(()=>loadArtifacts(true));
document.getElementById('deleteSelectedArtifactsBtn').onclick=()=>safe(async()=>{if(!can('files.write')){toast('Permission required: files.write');return}const turnIds=[...state.selectedArtifactTurns];if(turnIds.length===0){toast('No artifact turns selected');return}if(confirm('Delete '+turnIds.length+' selected artifact turn(s)?')){const r=await api('/api/artifacts/bulk',{method:'POST',body:JSON.stringify({action:'delete',turnIds})});state.selectedArtifactTurns.clear();toast('Deleted '+(r.removed||[]).length+' artifact turn(s)');loadArtifacts()}});
function highlightCode(text,language=''){let html=esc(text);html=html.replace(/(&quot;[^&]*?&quot;|'[^']*?'|`[^`]*?`)/g,'<span class="syntax-string">$1</span>');html=html.replace(/\\b(\\d+(?:\\.\\d+)?)\\b/g,'<span class="syntax-number">$1</span>');html=html.replace(/\\b(import|export|const|let|var|function|return|if|else|for|while|class|interface|type|async|await|try|catch|throw|new|public|private|protected|static|from|extends|implements|def|fn|struct|enum|match|use|mod)\\b/g,'<span class="syntax-keyword">$1</span>');if(['json','yaml','toml','markdown','md'].includes(language))html=html.replace(/^([\\w.-]+)(:|=)/gm,'<span class="syntax-keyword">$1</span>$2');return html}
function highlightDiff(text){return esc(text).split('\n').map(line=>{const cls=line.startsWith('+')?'diff-add':line.startsWith('-')?'diff-del':line.startsWith('@@')?'diff-hunk':'';return '<span class="'+cls+'">'+line+'</span>'}).join('\n')}
function splitDiff(text){const rows=[];let oldNo=0,newNo=0;for(const line of String(text||'').split('\n')){const h=line.match(/^@@ -(\\d+)/);const h2=line.match(/^@@ -\\d+(?:,\\d+)? \\+(\\d+)/);if(h)oldNo=Number(h[1])-1;if(h2)newNo=Number(h2[1])-1;if(line.startsWith('@@')){rows.push('<tr class="diff-split-hunk"><td colspan="4">'+esc(line)+'</td></tr>');continue}if(line.startsWith('-')){oldNo+=1;rows.push('<tr><td class="diff-line-no">'+oldNo+'</td><td class="diff-del">'+esc(line.slice(1))+'</td><td class="diff-line-no"></td><td></td></tr>');continue}if(line.startsWith('+')){newNo+=1;rows.push('<tr><td class="diff-line-no"></td><td></td><td class="diff-line-no">'+newNo+'</td><td class="diff-add">'+esc(line.slice(1))+'</td></tr>');continue}oldNo+=1;newNo+=1;rows.push('<tr><td class="diff-line-no">'+oldNo+'</td><td>'+esc(line.startsWith(' ')?line.slice(1):line)+'</td><td class="diff-line-no">'+newNo+'</td><td>'+esc(line.startsWith(' ')?line.slice(1):line)+'</td></tr>')}return '<div class="data-table-wrap"><table class="data-table diff-split-table"><thead><tr><th>Old</th><th>Before</th><th>New</th><th>After</th></tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'}
function isRemotePeerTarget(){return Boolean(state.selectedPeer&&state.selectedPeer!=='local')}
function artifactFileHref(turnId,path){return isRemotePeerTarget()?'#':'/api/artifacts/file?turnId='+encodeURIComponent(turnId)+'&path='+encodeURIComponent(path)}
function artifactZipHref(turnId){return isRemotePeerTarget()?'#':'/api/artifacts/zip?turnId='+encodeURIComponent(turnId)}
function downloadTextFile(name,text,mimeType='text/plain'){const blob=new Blob([text],{type:mimeType});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function downloadArtifactFile(turnId,path){const file=await api('/api/artifacts/file',{query:{turnId,path}});downloadBase64(file.name||path,file.dataBase64||'',file.mimeType||'application/octet-stream')}
async function downloadArtifactZip(turnId){const file=await api('/api/artifacts/zip',{query:{turnId}});downloadBase64(file.name||('nordrelay-artifacts-'+turnId+'.zip'),file.dataBase64||'',file.mimeType||'application/zip')}
async function artifactDataUrl(turnId,path){const file=await api('/api/artifacts/file',{query:{turnId,path}});return 'data:'+(file.mimeType||'application/octet-stream')+';base64,'+(file.dataBase64||'')}
function artifactStatusClass(status){return status==='over'?'disabled':status==='warn'?'planned':'enabled'}
function renderArtifactUsage(usage){const target=document.getElementById('artifactUsage');if(!target)return;if(!usage){target.innerHTML='';return}if(usage.error){target.innerHTML='<div class="item error">'+esc(usage.error)+'</div>';return}const quota=usage.maxTotalBytes>0?(fmtBytes(usage.managedBytes)+' / '+fmtBytes(usage.maxTotalBytes)+' ('+Math.round(usage.usagePercent||0)+'%)'):fmtBytes(usage.managedBytes)+' managed';const rows=[['Quota',quota],['Referenced',fmtBytes(usage.referencedBytes||0)],['Turns',String(usage.indexedTurns||0)],['Files',String(usage.indexedFiles||0)],['Skipped',String(usage.skippedFiles||0)],['Newest',fmtDate(usage.newestUpdatedAt)],['Largest',usage.largestTurn?usage.largestTurn.turnId+' · '+fmtBytes(usage.largestTurn.sizeBytes):'-']];target.innerHTML='<div class="data-table-wrap artifact-usage-table"><table class="data-table"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody>'+rows.map(row=>'<tr><td data-label="Metric" class="primary-cell">'+esc(row[0])+'</td><td data-label="Value"><span class="truncate-cell" title="'+attr(row[1])+'">'+esc(row[1])+'</span></td></tr>').join('')+'</tbody></table></div><span class="adapter-status '+artifactStatusClass(usage.status)+'">'+esc(usage.status||'ok')+'</span>'}
function renderCleanupPlan(plan){const target=document.getElementById('artifactCleanupPlan');if(!target)return;if(!plan){target.innerHTML='';return}const title=plan.dryRun?'Cleanup preview':'Cleanup result';const summary=plan.candidates.length+' candidates · '+fmtBytes(plan.removedBytes||0)+' · '+plan.removedTurnDirs+' turns · '+plan.removedInboxDirs+' inbox dirs';const rows=(plan.candidates||[]).slice(0,50).map(c=>'<tr><td data-label="Type" class="primary-cell">'+esc(c.kind)+'</td><td data-label="ID"><span class="truncate-cell" title="'+attr(c.id)+'">'+esc(short(c.id,80))+'</span></td><td data-label="Size">'+esc(fmtBytes(c.sizeBytes||0))+'</td><td data-label="Updated">'+esc(fmtDate(c.updatedAt))+'</td><td data-label="Reason"><span class="truncate-cell" title="'+attr((c.reasons||[]).join(', '))+'">'+esc((c.reasons||[]).join(', ')||'-')+'</span></td></tr>').join('');target.innerHTML='<div class="item artifact-cleanup-summary"><strong>'+esc(title)+'</strong><small>'+esc(summary)+'</small></div>'+(rows?'<div class="data-table-wrap"><table class="data-table artifact-cleanup-table"><thead><tr><th>Type</th><th>ID</th><th>Size</th><th>Updated</th><th>Reason</th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="item">No cleanup candidates.</div>')}
async function previewArtifactCleanup(){if(!can('files.write')){toast('Permission required: files.write');return}setLoading('artifactCleanupPlan','Planning cleanup...');const plan=await api('/api/artifacts/cleanup/preview',{method:'POST',body:JSON.stringify({})});renderCleanupPlan(plan)}
async function runArtifactCleanup(){if(!can('files.write')){toast('Permission required: files.write');return}if(!confirm('Run artifact cleanup for the current workspace?'))return;setLoading('artifactCleanupPlan','Running cleanup...');const plan=await api('/api/artifacts/cleanup/run',{method:'POST',body:JSON.stringify({})});renderCleanupPlan(plan);toast('Removed '+fmtBytes(plan.removedBytes||0));await loadArtifacts(true)}
function artifactSafeBadge(a){return a.safeStatus&&a.safeStatus!=='ok'?'<span class="adapter-status '+(a.safeStatus==='blocked'?'disabled':'planned')+'" title="'+attr((a.safeWarnings||[]).join(', '))+'">'+esc(a.safeStatus)+'</span>':''}
function artifactProvenanceText(r){const p=r.provenance||{};return [fmtDate(r.updatedAt),p.source||r.source||'turn',p.agentId,p.threadId,p.contextKey,p.actor?.label||p.actor?.username||p.actor?.channelUserId,p.workspace||state.snapshot?.session?.workspace||'workspace'].filter(Boolean).join(' | ')}
function artifactProvenanceTitle(r){const p=r.provenance||{};return [['Source',p.source||r.source],['Agent',p.agentId],['Thread',p.threadId],['Context',p.contextKey],['Actor',p.actor?.label||p.actor?.username||p.actor?.channelUserId],['Workspace',p.workspace],['Correlation',p.correlationId],['Started',p.turnStartedAt?fmtDate(p.turnStartedAt):''],['Prompt',p.prompt]].filter(row=>row[1]).map(row=>row[0]+': '+row[1]).join('\n')}
function renderArtifacts(){const query=(document.getElementById('artifactSearch').value||'').toLowerCase();const kind=document.getElementById('artifactKind').value;const reports=state.artifactReports||[];document.getElementById('artifactList').innerHTML=reports.map(r=>{const files=(r.artifacts||[]).filter(a=>artifactMatches(a,kind,query));if(files.length===0)return'';const imageFiles=files.filter(a=>/\\.(png|jpe?g|gif|webp|svg)$/i.test(a.name));const imageStrip=imageFiles.length?'<div class="artifact-image-strip">'+imageFiles.slice(0,8).map(a=>'<button type="button" data-preview-turn="'+attr(r.turnId)+'" data-preview-path="'+attr(a.relativePath)+'"><img src="'+artifactFileHref(r.turnId,a.relativePath)+'" alt=""></button>').join('')+'</div>':'';const gallery=files.map(a=>{const href=artifactFileHref(r.turnId,a.relativePath);const isImage=/\\.(png|jpe?g|gif|webp|svg)$/i.test(a.name);const img=isImage&&!isRemotePeerTarget()?'<img src="'+href+'">':'<pre>'+esc((a.name.split('.').pop()||'file').slice(0,12))+'</pre>';const open='<a href="'+href+'" data-open-artifact="'+attr(r.turnId)+'" data-open-path="'+attr(a.relativePath)+'">Open</a>';return '<div class="artifact-card"><label><input type="checkbox" data-artifact-select="'+attr(r.turnId)+'" '+(state.selectedArtifactTurns.has(r.turnId)?'checked':'')+'> '+esc(short(a.name,32))+' '+artifactSafeBadge(a)+'</label>'+img+'<small>'+esc(fmtBytes(a.sizeBytes))+'</small><div class="row">'+open+'<button class="secondary" data-preview-turn="'+attr(r.turnId)+'" data-preview-path="'+attr(a.relativePath)+'">Preview</button><button class="secondary" data-diff-turn="'+attr(r.turnId)+'" data-diff-path="'+attr(a.relativePath)+'">Diff</button></div></div>'}).join('');return '<div class="item"><strong>'+esc(r.turnId)+' - '+files.length+'/'+r.fileCount+' files - '+fmtBytes(r.totalSizeBytes)+'</strong><small title="'+attr(artifactProvenanceTitle(r))+'">'+esc(artifactProvenanceText(r))+'</small><div class="row"><a href="'+artifactZipHref(r.turnId)+'" data-zip-artifact="'+attr(r.turnId)+'">Download ZIP</a><button data-del-art="'+esc(r.turnId)+'" class="danger"'+disabledAttr('files.write')+'>Delete</button></div>'+imageStrip+'<div class="gallery">'+gallery+'</div></div>'}).join('')||'<div class="item">No artifacts.</div>';document.querySelectorAll('[data-artifact-select]').forEach(c=>c.onchange=()=>{if(c.checked)state.selectedArtifactTurns.add(c.dataset.artifactSelect);else state.selectedArtifactTurns.delete(c.dataset.artifactSelect)});document.querySelectorAll('[data-open-artifact]').forEach(a=>a.onclick=e=>{if(!isRemotePeerTarget())return;e.preventDefault();safe(()=>downloadArtifactFile(a.dataset.openArtifact,a.dataset.openPath))});document.querySelectorAll('[data-zip-artifact]').forEach(a=>a.onclick=e=>{if(!isRemotePeerTarget())return;e.preventDefault();safe(()=>downloadArtifactZip(a.dataset.zipArtifact))});document.querySelectorAll('[data-del-art]').forEach(b=>b.onclick=()=>safe(async()=>{if(!can('files.write')){toast('Permission required: files.write');return}if(confirm('Delete artifact turn '+b.dataset.delArt+'?')){await api('/api/artifacts',{method:'DELETE',query:{turnId:b.dataset.delArt}});state.selectedArtifactTurns.delete(b.dataset.delArt);loadArtifacts()}}));document.querySelectorAll('[data-preview-turn]').forEach(b=>b.onclick=()=>safe(()=>previewArtifact(b.dataset.previewTurn,b.dataset.previewPath)));document.querySelectorAll('[data-diff-turn]').forEach(b=>b.onclick=()=>safe(()=>previewArtifactDiff(b.dataset.diffTurn,b.dataset.diffPath)));applyPermissions()}
document.getElementById('zipSelectedArtifactsBtn').onclick=()=>{const turnIds=[...state.selectedArtifactTurns];if(turnIds.length===0){toast('No artifact turns selected');return}turnIds.forEach(turnId=>isRemotePeerTarget()?safe(()=>downloadArtifactZip(turnId)):window.open('/api/artifacts/zip?turnId='+encodeURIComponent(turnId),'_blank'))};
document.getElementById('previewArtifactCleanupBtn').onclick=()=>safe(previewArtifactCleanup);
document.getElementById('runArtifactCleanupBtn').onclick=()=>safe(runArtifactCleanup);
function artifactPreviewTitle(data,kind){const meta=[kind,data.language,data.lineCount?data.lineCount+' lines':'',fmtBytes(data.sizeBytes||0)].filter(Boolean).join(' | ');return '<h2>'+esc(data.name)+' <small>'+esc(meta)+'</small></h2>'}
async function previewArtifact(turnId,path){const target=document.getElementById('artifactPreview');target.innerHTML='<div class="panel">'+loadingHtml('Loading preview...')+'</div>';target.scrollIntoView({block:'start',behavior:'smooth'});try{const data=await api('/api/artifacts/preview',{query:{turnId,path}});const safe=data.safeStatus&&data.safeStatus!=='ok'?'<p class="artifact-safe-warning">'+esc((data.safeWarnings||[]).join(', ')||data.safeStatus)+'</p>':'';if(data.kind==='image'){const src=isRemotePeerTarget()?await artifactDataUrl(turnId,path):'/api/artifacts/file?turnId='+encodeURIComponent(turnId)+'&path='+encodeURIComponent(path);target.innerHTML='<div class="panel artifact-preview-panel">'+artifactPreviewTitle(data,'image')+safe+'<img src="'+src+'"></div>';return}if(data.kind==='text'){target.innerHTML='<div class="panel artifact-preview-panel">'+artifactPreviewTitle(data,'text')+safe+'<pre>'+highlightCode(data.text||'',data.language||'')+'</pre>'+(data.truncated?'<small>Preview truncated.</small>':'')+'</div>';return}target.innerHTML='<div class="panel artifact-preview-panel">'+artifactPreviewTitle(data,data.kind||'file')+safe+'<p>'+esc(data.detail||'Preview unavailable')+'</p></div>'}catch(err){target.innerHTML='<div class="panel"><h2>Preview failed</h2><p>'+esc(err.message||String(err))+'</p></div>';throw err}}
async function previewArtifactDiff(turnId,path){const target=document.getElementById('artifactPreview');target.innerHTML='<div class="panel">'+loadingHtml('Loading diff...')+'</div>';target.scrollIntoView({block:'start',behavior:'smooth'});try{const data=await api('/api/artifacts/diff',{query:{turnId,path}});if(data.kind==='diff'){target.innerHTML='<div class="panel artifact-preview-panel"><h2>'+esc(data.name)+' <small>side-by-side diff</small></h2>'+splitDiff(data.text||'')+'<details><summary>Unified diff</summary><pre class="code-diff">'+highlightDiff(data.text||'')+'</pre></details>'+(data.truncated?'<small>Diff truncated.</small>':'')+'</div>';return}target.innerHTML='<div class="panel artifact-preview-panel"><h2>'+esc(data.name||path)+' <small>diff unavailable</small></h2><p>'+esc(data.detail||'No diff available.')+'</p></div>'}catch(err){target.innerHTML='<div class="panel"><h2>Diff failed</h2><p>'+esc(err.message||String(err))+'</p></div>';throw err}}
